const dev = (k, o) => (D[k] || D.dpi)(o);
// ---------------- scenes ----------------
const S = {};
// common inhaler scenes; o.device selects device
S['inh-device'] = o => G(dev(o.device, { ...o, cap: false, open: true, capOpen: true }), 90, 120) + num(1, 84, 120) + num(2, 210, 120);
S['cap-off'] = o => G(dev(o.device, { ...o, cap: false, capOpen: true, open: true }), 120, 125) + R(48, 108, 26, 34, o.capColor || '#334155', 5) + arrow(82, 125, 40, 125, AIR) + num(1, 120, 160) + num(2, 60, 90);
