S['prime-respimat'] = o => G(dev('respimat', { ...o, capOpen: true }), 165, 130, 180, .62) + `<g opacity=".85">${[0, 1, 2, 3].map(i => `<circle cx="${158 + (i % 2 ? 8 : -8)}" cy="${152 + i * 14}" r="${4 + i * 3}" fill="#bfdbfe"/>`).join('')}</g>` + arrow(250, 120, 250, 200, AIR) + num(1, 85, 60) + num(2, 280, 160);
S['exhale-away'] = o => head(140, 110, 'o') + breath(186, 128, 'out', 60) + G(dev(o.device, { ...o, open: true, capOpen: true }), 60, 196, 0, .6) + ok(270, 60) + num(1, 140, 30) + num(2, 90, 170);
