export function illustrate(id, opts = {}, alt = '') {
  const f = S[id] || S['generic-device'];
  let inner;
  try { inner = f(opts); } catch (e) { inner = S['generic-device'](opts); }
  return `<svg class="ill" viewBox="0 0 320 220" role="img" aria-label="${esc(alt)}" focusable="false" xmlns="http://www.w3.org/2000/svg"><title>${esc(alt)}</title><rect x="1.5" y="1.5" width="317" height="217" rx="16" fill="#fffdf7" stroke="#e7dcc6" stroke-width="3"/>${inner}</svg>`;
}
